# Rule: A 7 changes to 4 if it has FEWER than N foreground neighbors

def count_neighbors(r, c, grid):
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 7:
                    count += 1
    return count

