# Let me verify my 2x2 rule one more time and generate the final output
def count_2x2_around(r, c, grid, target=3):
    """Check if any 2x2 block overlapping (r,c) has exactly 3 foreground cells (not counting (r,c))"""
    for dr in [0, -1]:
        for dc in [0, -1]:
            br, bc = r+dr, c+dc
            block_count = 0
            block_cells = []
            for i in [0, 1]:
                for j in [0, 1]:
                    nr, nc = br+i, bc+j
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == target:
                            block_count += 1
                        block_cells.append((nr, nc))
            if block_count == 3:
                return True  # (r,c) completes a block
    return False

