def is_adjacent(row, c):
    """Check if position (row, c) has an adjacent 3 in the same row."""
    if 0 < c < len(row) - 1:
        return row[c-1] == 3 or row[c+1] == 3
    if c == 0:
        return row[1] == 3
    if c == len(row) - 1:
        return row[c-1] == 3
    return False

